import type { Nic, CableOrOptic, VendorInfo, Vendor, CatalogBase } from '../types';

type Cx = [string, string, string[]];
const cdx = ([summary, explain, tradeoffs]: Cx): CatalogBase['codex'] => ({ summary, explain, tradeoffs, tags: [] });
const base = (id: string, name: string, vendor: Vendor, from: number, price: number, lead: number, c: Cx, tags: string[] = [], eol?: number) =>
  ({ id, name, vendor, availableFrom: from, ...(eol ? { eolAfter: eol } : {}), priceUSD: price, leadTimeMonths: lead, codex: { ...cdx(c), tags } });
const nic = (o: Omit<Nic, 'kind'>): Nic => ({ kind: 'nic', ...o });
const cb = (o: Omit<CableOrOptic, 'kind'>): CableOrOptic => ({ kind: 'cable', ...o });

